"""ETL Pipeline - Level 1 (Pandas)Movie Recommendation SystemThis script automates the ETL process:- Extract: Read CSV files from data/raw/- Transform: Clean data (convert timestamps)- Load: Insert into MySQL database"""import osimport pandas as pdfrom sqlalchemy import create_engine, textfrom dotenv import load_dotenvfrom urllib.parse import quote_plusimport time# ============================================# CONFIGURATION# ============================================# Load environment variablesload_dotenv()# Database connection parametersDB_USER = 'root'DB_PASSWORD = os.getenv('MYSQL_ROOT_PASSWORD')DB_HOST = os.getenv('MYSQL_HOST', 'localhost')DB_PORT = os.getenv('MYSQL_PORT', '2004')DB_NAME = os.getenv('MYSQL_DATABASE', 'movie_recommendation')# File pathsRAW_DATA_PATH = 'data/raw/'MOVIES_FILE = os.path.join(RAW_DATA_PATH, 'movies.csv')RATINGS_FILE = os.path.join(RAW_DATA_PATH, 'ratings.csv')# ============================================# EXTRACT FUNCTION# ============================================def extract():    """Extract data from CSV files"""    print("\n EXTRACT PHASE")    print("-" * 30)        try:        # Read movies.csv        print(f"Reading movies from: {MOVIES_FILE}")        df_movies = pd.read_csv(MOVIES_FILE)        print(f"    {len(df_movies):,} movies loaded")                # Read ratings.csv        print(f"Reading ratings from: {RATINGS_FILE}")        df_ratings = pd.read_csv(RATINGS_FILE)        print(f"    {len(df_ratings):,} ratings loaded")                return df_movies, df_ratings            except FileNotFoundError as e:        print(f" File not found: {e}")        print("   Check that CSV files exist in data/raw/")        raise    except Exception as e:        print(f" Error during extract: {e}")        raise# ============================================# TRANSFORM FUNCTION# ============================================def transform(df_movies, df_ratings):    """Clean and prepare data"""    print("\n🔄 TRANSFORM PHASE")    print("-" * 30)        try:        # Make copies to avoid modifying originals        movies = df_movies.copy()        ratings = df_ratings.copy()                # Transform 1: Convert timestamps to datetime        print("Converting timestamps...")        ratings['datetime'] = pd.to_datetime(ratings['timestamp'], unit='s')        print(f"   ✅ Date range: {ratings['datetime'].min()} to {ratings['datetime'].max()}")                # Transform 2: Add year column to ratings (useful for analysis)        ratings['year'] = ratings['datetime'].dt.year                # Transform 3: Extract year from movie titles        print("\nExtracting year from titles...")        movies['year'] = movies['title'].str.extract(r'\((\d{4})\)').astype(float)        print(f"   ✅ Year extracted for {movies['year'].notna().sum()} movies")        print(f"   📅 Years range: {movies['year'].min():.0f} - {movies['year'].max():.0f}")                # Analyze movies without year (informational only)        movies_without_year = movies[movies['year'].isna()]        if len(movies_without_year) > 0:            print(f"\n🔍 Note: {len(movies_without_year)} movies have no year in title")            print(f"   These will remain as NULL in the database")            print(f"   Examples:")            for idx, row in movies_without_year.head(5).iterrows():                print(f"   - {row['title']} (ID: {row['movieId']})")                # Statistics by decade (for information only)        print("\n📊 Movies per decade (with year):")        movies_with_year = movies[movies['year'].notna()]        decade_stats = movies_with_year['year'].apply(            lambda x: f"{int(x//10*10)}s"        ).value_counts().sort_index()        for decade, count in decade_stats.items():            print(f"   {decade}: {count} movies")                # Quick validation        print("\nValidating data...")        print(f"   Movies missing values (excluding intentional NULLs):")        print(f"      - title: {movies['title'].isnull().sum()}")        print(f"      - genres: {movies['genres'].isnull().sum()}")        print(f"      - year: {movies['year'].isnull().sum()} (expected)")        print(f"   Ratings missing values: {ratings.isnull().sum().sum()}")                # Keep only necessary columns for database        # We keep original timestamp, but also have datetime for analysis        ratings_db = ratings[['userId', 'movieId', 'rating', 'timestamp']]                print(f"\n✅ Transform complete")        print(f"   Movies: {len(movies)} rows (year column added with {movies['year'].isnull().sum()} NULLs)")        print(f"   Ratings: {len(ratings)} rows")                return movies, ratings_db            except Exception as e:        print(f"❌ Error during transform: {e}")        raise        raise# ============================================# LOAD FUNCTION# ============================================def load(movies, ratings):    """Load data into MySQL database"""    print("\n LOAD PHASE")    print("-" * 30)        try:        # Create connection string with encoded password        encoded_password = quote_plus(DB_PASSWORD)        connection_string = f"mysql+mysqlconnector://{DB_USER}:{encoded_password}@{DB_HOST}:{DB_PORT}/{DB_NAME}"        engine = create_engine(connection_string)                # Test connection        with engine.connect() as conn:            conn.execute(text("SELECT 1"))            print(" Database connection OK")                # Get counts before        with engine.connect() as conn:            movie_before = conn.execute(text("SELECT COUNT(*) FROM movies")).scalar()            rating_before = conn.execute(text("SELECT COUNT(*) FROM ratings")).scalar()                print(f"\n Before load:")        print(f"   Movies in table: {movie_before}")        print(f"   Ratings in table: {rating_before}")                # Drop tables in correct order (child first)        print("\n  Preparing tables...")        with engine.connect() as conn:            conn.execute(text("SET FOREIGN_KEY_CHECKS = 0"))            conn.execute(text("DROP TABLE IF EXISTS ratings"))            conn.execute(text("DROP TABLE IF EXISTS movies"))            conn.execute(text("SET FOREIGN_KEY_CHECKS = 1"))            conn.commit()        print("    Tables dropped")                # Load movies        print("\n Loading movies...")        start = time.time()        movies.to_sql('movies', engine, if_exists='replace', index=False)        end = time.time()        print(f"    {len(movies)} movies loaded in {end-start:.2f} seconds")                # Load ratings        print("\n Loading ratings...")        start = time.time()        ratings.to_sql('ratings', engine, if_exists='replace', index=False)        end = time.time()        print(f"    {len(ratings)} ratings loaded in {end-start:.2f} seconds")                # Get counts after        with engine.connect() as conn:            movie_after = conn.execute(text("SELECT COUNT(*) FROM movies")).scalar()            rating_after = conn.execute(text("SELECT COUNT(*) FROM ratings")).scalar()                print(f"\n After load:")        print(f"   Movies in table: {movie_after}")        print(f"   Ratings in table: {rating_after}")                # Verify integrity (quick sample)        with engine.connect() as conn:            result = conn.execute(text("""                SELECT COUNT(*) FROM ratings r                 LEFT JOIN movies m ON r.movieId = m.movieId                 WHERE m.movieId IS NULL            """)).scalar()                if result == 0:            print("\n Foreign key integrity verified: all ratings match a movie")        else:            print(f"\n Warning: {result} ratings with no matching movie")                return engine            except Exception as e:        print(f" Error during load: {e}")        raisedef main():    """Main ETL function"""    print("="*50)    print(" ETL PIPELINE STARTED")    print("="*50)        # Display configuration (without password)    print(f"\n Configuration:")    print(f"   Database: {DB_NAME} on {DB_HOST}:{DB_PORT}")    print(f"   Movies file: {MOVIES_FILE}")    print(f"   Ratings file: {RATINGS_FILE}")        # EXTRACT    df_movies, df_ratings = extract()        print("\n" + "="*50)    print(" ETL PIPELINE COMPLETED")    print("="*50)        print("\n" + "="*50)    print(" ETL PIPELINE COMPLETED")    print("="*50) # TRANSFORM    movies_clean, ratings_clean = transform(df_movies, df_ratings)        print("\n" + "="*50)    print(" ETL PIPELINE COMPLETED")    print("="*50) # LOAD    engine = load(movies_clean, ratings_clean)        print("\n" + "="*50)    print(" ETL PIPELINE COMPLETED")    print("="*50)if __name__ == "__main__":    main()